const body = $json.body || {};
const name  = body.company_name || 'there';
const email = (body.email || '').trim();
const approved = (body.status || '').toLowerCase() === 'approved';

const subject = approved
  ? 'Your H!RE company account has been approved'
  : 'Update on your H!RE company registration';

const html = approved
  ? `<div style="font-family: Arial, sans-serif; max-width:600px; margin:0 auto; color:#0d1b3e;">\n  <h2 style="color:#f97316;">You're approved! \uD83C\uDF89</h2>\n  <p>Hi ${name},</p>\n  <p>Great news — your company account has been approved by the H!RE admin team. You can now log in as the company owner and start setting up your hiring workflow.</p>\n  <br/>\n  <p>Best regards,<br/><strong>The H!RE Team</strong></p>\n</div>`
  : `<div style="font-family: Arial, sans-serif; max-width:600px; margin:0 auto; color:#0d1b3e;">\n  <h2 style="color:#f97316;">Registration Update</h2>\n  <p>Hi ${name},</p>\n  <p>Thank you for your interest in H!RE. After review, your company registration was not approved at this time. If you believe this was a mistake or would like more information, please contact our support team.</p>\n  <br/>\n  <p>Best regards,<br/><strong>The H!RE Team</strong></p>\n</div>`;

return [{ json: { recipient_email: email, email_subject: subject, email_html: html } }];
